pm.sendRequest(
    {
        url: pm.collectionVariables.get("baseUrl") + "/api/students",
        method: "GET"
    },
    function (err, response) {
        if (err) {
            console.error("Could not retrieve students:", err);
            return;
        }

        const body = response.json();
        const students = body.data;

        if (!Array.isArray(students) || students.length === 0) {
            console.error("No students available to delete.");
            return;
        }

        pm.collectionVariables.set(
            "deleteStudentId",
            String(students[0].id)
        );
    }
);

